"""Shared plotting style. Every figure is generated by a script from results/*.csv.

Figures are emitted in two themes: ``light`` for the PDF paper (white page) and
``dark`` for the website (#0a0a0a background). Call ``use_style(theme)`` before
plotting and read colours from the module-level ``INK``/``PALETTE`` helpers,
which are rebound to the active theme.
"""
from __future__ import annotations

import matplotlib as mpl
import matplotlib.pyplot as plt

# Method palette. Deliberately not matplotlib's tab10: the two series that carry
# the comparison must stay distinguishable under deuteranopia, so the contrast is
# warm-vs-teal rather than the default red-vs-green.
#   marginal  - the method that fails; warm amber, the only warm hue in the figure
#   mondrian  - the site accent teal
#   weighted  - a desaturated slate that sits back from the other two
METHOD_COLORS = {"marginal": "#c8783c", "mondrian": "#7fb5b5", "weighted": "#6b7a85"}

# Seven models need seven separable hues, not shades of the method palette:
# paired variants (af3/af3_no_template, boltz/boltz1x) must stay tellable apart
# in a narrow column, so each gets its own hue rather than a lighter tint of its
# sibling. Ordered around the wheel and checked for deuteranopia separation.
MODEL_COLORS = {
    "af3": "#7fb5b5",              # site teal - the reference model
    "af3_no_template": "#4a7d96",  # deeper blue, clearly not the teal
    "boltz": "#c8783c",            # amber
    "boltz1x": "#b8484f",          # rose - a different hue, not a darker amber
    "boltz2": "#8a6a55",           # warm taupe
    "chai": "#6b8f71",             # muted green
    "protenix": "#8f7fa8",         # muted violet
    "rfaa": "#6b7a85",             # slate - excluded from cutoff analysis
}

_THEMES = {
    "light": {
        "bg": "#ffffff",
        "ink": "#1a1a1a",        # primary text
        "muted": "#6b6b6b",      # secondary text, tick labels
        "rule": "#d8d8d6",       # axis spines
        "grid": "#e8e8e6",
        "zone": "#c8783c",       # violation shading
        "zone_alpha": 0.07,
    },
    "dark": {
        "bg": "#0a0a0a",
        "ink": "#ececea",
        "muted": "#8c8c8a",
        "rule": "#2e2e30",
        "grid": "#1e1e1f",
        "zone": "#c8783c",
        "zone_alpha": 0.10,
    },
}

# Rebound by use_style(); import the module and read style.INK to stay in sync.
THEME = "light"
INK = _THEMES["light"]["ink"]
MUTED = _THEMES["light"]["muted"]
RULE = _THEMES["light"]["rule"]
GRID = _THEMES["light"]["grid"]
ZONE = _THEMES["light"]["zone"]
ZONE_ALPHA = _THEMES["light"]["zone_alpha"]
BG = _THEMES["light"]["bg"]

# Helvetica Neue tracks the site's Inter closely and is present on the build
# machine; DejaVu is matplotlib's fallback and looks like an unstyled default.
_FONT_STACK = ["Helvetica Neue", "Helvetica", "Arial", "DejaVu Sans"]


def use_style(theme: str = "light") -> None:
    """Install the shared rcParams for ``theme`` and rebind the colour globals."""
    global THEME, INK, MUTED, RULE, GRID, ZONE, ZONE_ALPHA, BG
    t = _THEMES[theme]
    THEME, INK, MUTED = theme, t["ink"], t["muted"]
    RULE, GRID, ZONE, ZONE_ALPHA, BG = t["rule"], t["grid"], t["zone"], t["zone_alpha"], t["bg"]

    mpl.rcParams.update({
        "figure.dpi": 150, "savefig.dpi": 200, "savefig.bbox": "tight",
        "savefig.pad_inches": 0.25,
        "figure.facecolor": t["bg"], "axes.facecolor": t["bg"], "savefig.facecolor": t["bg"],

        "font.family": "sans-serif", "font.sans-serif": _FONT_STACK,
        # Sized for a ~700px column: the figure is downscaled in the page, so
        # anything smaller than this stops being readable on the site.
        "font.size": 10.5, "axes.titlesize": 11.5, "axes.labelsize": 10.5,
        "axes.titleweight": "medium", "axes.titlepad": 10, "axes.labelpad": 6,

        "text.color": t["ink"], "axes.labelcolor": t["muted"],
        "xtick.color": t["muted"], "ytick.color": t["muted"],
        "xtick.labelcolor": t["muted"], "ytick.labelcolor": t["muted"],
        "xtick.labelsize": 10, "ytick.labelsize": 10,

        # Only a left spine and a baseline: the grid already carries the reading.
        "axes.spines.top": False, "axes.spines.right": False,
        "axes.spines.left": True, "axes.spines.bottom": True,
        "axes.edgecolor": t["rule"], "axes.linewidth": 0.8,
        "xtick.major.size": 0, "ytick.major.size": 0, "xtick.major.pad": 6,

        # Horizontal grid only. Vertical rules add nothing when x is categorical.
        "axes.grid": True, "axes.grid.axis": "y",
        "grid.color": t["grid"], "grid.linewidth": 0.8, "grid.alpha": 1.0,
        "axes.axisbelow": True,

        "legend.frameon": False, "legend.fontsize": 10,
        "legend.labelcolor": t["ink"], "legend.handlelength": 1.6,
        "legend.handletextpad": 0.6, "legend.columnspacing": 1.4,

        "lines.solid_capstyle": "round",
    })


def bin_order(bins) -> list:
    return sorted([b for b in bins if isinstance(b, str) and b != "all"], key=lambda b: float(b.split("-")[0]))


def bin_label(b: str) -> str:
    """Axis-friendly bin label with an en dash rather than a hyphen."""
    return b.replace("-", "–")


def emphasis(method: str) -> dict:
    """Line weight per method.

    The argument is about ``marginal`` failing, so it carries full weight and the
    comparison methods sit back. Hierarchy, not decoration.
    """
    if method == "marginal":
        return {"lw": 2.2, "ms": 5.5, "alpha": 1.0, "zorder": 3}
    return {"lw": 1.5, "ms": 4.0, "alpha": 0.9, "zorder": 2}
